import { useEffect, useState } from "react";
import axios from "axios";

function Dashboard() {
  // Jobs State
  const [jobs, setJobs] = useState([]);

  // Form States
  const [company, setCompany] = useState("");
  const [role, setRole] = useState("");
  const [status, setStatus] = useState("Applied");

  // Search State
  const [search, setSearch] = useState("");

  /* =========================
     FETCH JOBS
  ========================= */
  const fetchJobs = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/jobs");

      setJobs(res.data);

    } catch (error) {
      console.log(error);
    }
  };

  /* =========================
     ADD JOB
  ========================= */
  const addJob = async () => {
    if (!company || !role) {
      alert("Please fill all fields");
      return;
    }

    try {
      await axios.post("http://localhost:5000/api/jobs", {
        company,
        role,
        status,
      });

      // Clear inputs
      setCompany("");
      setRole("");
      setStatus("Applied");

      // Refresh jobs
      fetchJobs();

    } catch (error) {
      console.log(error);
    }
  };

  /* =========================
     DELETE JOB
  ========================= */
  const deleteJob = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/api/jobs/${id}`);

      fetchJobs();

    } catch (error) {
      console.log(error);
    }
  };

  /* =========================
     LOAD JOBS ON PAGE LOAD
  ========================= */
  useEffect(() => {
    fetchJobs();
  }, []);

  return (
    <div
      style={{
        padding: "40px",
        fontFamily: "Arial",
      }}
    >
      <h1>Smart Job Tracker 🚀</h1>

      {/* =========================
          INPUT SECTION
      ========================= */}
      <div
        style={{
          display: "flex",
          gap: "10px",
          marginTop: "20px",
          flexWrap: "wrap",
        }}
      >
        {/* Company Input */}
        <input
          type="text"
          placeholder="Company Name"
          value={company}
          onChange={(e) => setCompany(e.target.value)}
          style={{
            padding: "10px",
            width: "200px",
          }}
        />

        {/* Role Input */}
        <input
          type="text"
          placeholder="Role"
          value={role}
          onChange={(e) => setRole(e.target.value)}
          style={{
            padding: "10px",
            width: "200px",
          }}
        />

        {/* Status Dropdown */}
        <select
          value={status}
          onChange={(e) => setStatus(e.target.value)}
          style={{
            padding: "10px",
            width: "200px",
          }}
        >
          <option>Applied</option>
          <option>Interview</option>
          <option>Rejected</option>
          <option>Offer</option>
        </select>

        {/* Add Button */}
        <button
          onClick={addJob}
          style={{
            padding: "10px 20px",
            cursor: "pointer",
          }}
        >
          Add Job
        </button>
      </div>

      {/* =========================
          SEARCH INPUT
      ========================= */}
      <input
        type="text"
        placeholder="Search jobs..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        style={{
          padding: "10px",
          width: "300px",
          marginTop: "20px",
        }}
      />

      {/* =========================
          JOB LIST
      ========================= */}
      <div style={{ marginTop: "30px" }}>
        {jobs
          .filter((job) => {
            return (
              job.company
                .toLowerCase()
                .includes(search.toLowerCase()) ||
              job.role
                .toLowerCase()
                .includes(search.toLowerCase())
            );
          })
          .map((job) => (
            <div
              key={job.id}
              style={{
                border: "1px solid gray",
                padding: "15px",
                marginBottom: "10px",
                borderRadius: "10px",
              }}
            >
              <h3>{job.company}</h3>

              <p>{job.role}</p>

              <p>Status: {job.status}</p>

              <button
                onClick={() => deleteJob(job.id)}
                style={{
                  backgroundColor: "red",
                  color: "white",
                  padding: "8px",
                  border: "none",
                  cursor: "pointer",
                }}
              >
                Delete
              </button>
            </div>
          ))}
      </div>
    </div>
  );
}

export default Dashboard;
